  1	import {createHash} from "node:crypto";
  2	import {z} from "zod";
  3	
  4	/**
  5	 * A procedure is the single, human-reviewable source of operational knowledge.
  6	 * A compiled skill is an immutable runtime projection of that procedure. Nobody edits the
  7	 * compiled projection directly and no runtime is allowed to invent a peer-to-peer handoff.
  8	 */
  9	
 10	export const procedureCompilerVersion = "2026.08.25-v2";
 11	
 12	/**
 13	 * The ladder a method climbs. Nothing skips a rung: `implemented` needs executable evidence,
 14	 * `ai_reviewed` needs a recorded independent review by a model that went back to the sources,
 15	 * `tested` needs the gold, adversarial and consistency runs, `ready_for_founder` is the hand-off
 16	 * to the founder's integrated evaluation, and `production` needs the founder's approval.
 17	 */
 18	export const procedureMaturitySchema = z.enum(["draft", "candidate", "implemented", "ai_reviewed", "tested", "ready_for_founder", "production"]);
 19	export const procedureMaturityOrder: readonly ProcedureMaturity[] = ["draft", "candidate", "implemented", "ai_reviewed", "tested", "ready_for_founder", "production"];
 20	export const maturityRank = (maturity: ProcedureMaturity): number => procedureMaturityOrder.indexOf(maturity);
 21	export type ProcedureMaturity = z.infer<typeof procedureMaturitySchema>;
 22	
 23	export const procedureRoleSchema = z.enum([
 24	  "intake_evidence",
 25	  "financial_analysis",
 26	  "credit_structuring",
 27	  "institutional_materials",
 28	  "market_distribution",
 29	  "independent_quality_control",
 30	]);
 31	export type ProcedureRole = z.infer<typeof procedureRoleSchema>;
 32	
 33	export const procedureStageSchema = z.number().int().min(1).max(12);
 34	export type ProcedureStage = z.infer<typeof procedureStageSchema>;
 35	
 36	export const procedureAuthoritySchema = z.enum(["LEI", "DEF", "CASA", "MERCADO", "HEURÍSTICA"]);
 37	export type ProcedureAuthority = z.infer<typeof procedureAuthoritySchema>;
 38	
 39	const bilingualSchema = z.object({pt: z.string().trim().min(1), en: z.string().trim().min(1)}).strict();
 40	
 41	export const outputValueTypeSchema = z.enum([
 42	  "string",
 43	  "number",
 44	  "decimal_string",
 45	  "boolean",
 46	  "date",
 47	  "enum",
 48	  "object",
 49	  "array",
 50	]);
 51	
 52	export const procedureOutputFieldSchema = z.object({
 53	  id: z.string().regex(/^[a-z][a-z0-9_.-]*$/),
 54	  type: outputValueTypeSchema,
 55	  required: z.boolean(),
 56	  description: z.string().trim().min(1),
 57	  /** Material assertions must point to evidence or a traced calculation. */
 58	  evidenceRequired: z.boolean().default(true),
 59	  allowedValues: z.array(z.string().min(1)).min(1).optional(),
 60	}).strict();
 61	export type ProcedureOutputField = z.infer<typeof procedureOutputFieldSchema>;
 62	
 63	export const procedureStepSchema = z.object({
 64	  id: z.string().regex(/^[a-z][a-z0-9_-]*$/),
 65	  title: z.string().trim().min(1),
 66	  instructions: z.array(z.string().trim().min(1)).min(1),
 67	  mode: z.enum(["deterministic", "model_assisted", "human_judgment"]),
 68	  tools: z.array(z.string().trim().min(1)).default([]),
 69	  evidenceInputs: z.array(z.string().trim().min(1)).default([]),
 70	}).strict();
 71	export type ProcedureStep = z.infer<typeof procedureStepSchema>;
 72	
 73	const qualitySchema = z.object({
 74	  unit: z.array(z.string().trim().min(1)).min(1),
 75	  gold: z.array(z.string().trim().min(1)).min(1),
 76	  adversarial: z.array(z.string().trim().min(1)).min(1),
 77	  acceptance: z.array(z.string().trim().min(1)).min(1),
 78	}).strict();
 79	
 80	const runtimeSchema = z.object({
 81	  /** Roles are namespaces. The rail, not a model, owns order and transition. */
 82	  orchestration: z.literal("deterministic_pipeline"),
 83	  peerHandoffs: z.literal(false),
 84	  maxModelCalls: z.number().int().min(0).max(3),
 85	  modelPurpose: z.array(z.string().trim().min(1)).max(3).default([]),
 86	  allowedTools: z.array(z.string().trim().min(1)).default([]),
 87	}).strict();
 88	
 89	const implementationEvidenceSchema = z.object({
 90	  executor: z.object({
 91	    module: z.string().trim().min(1),
 92	    exportName: z.string().regex(/^[A-Za-z_$][A-Za-z0-9_$]*$/),
 93	  }).strict(),
 94	  resultContract: z.string().trim().min(1),
 95	  connectedProductStates: z.array(z.string().regex(/^[a-z][a-z0-9_]*$/)).min(1),
 96	  persistence: z.object({
 97	    mode: z.enum(["persisted", "derived_on_demand"]),
 98	    target: z.string().trim().min(1),
 99	  }).strict(),
100	  evaluation: z.object({
101	    unitTestFiles: z.array(z.string().trim().min(1)).min(1),
102	    goldCaseIds: z.array(z.string().trim().min(1)).min(1),
103	    adversarialCaseIds: z.array(z.string().trim().min(1)).min(1),
104	    e2eScenarioIds: z.array(z.string().trim().min(1)).min(1),
105	    costEvalIds: z.array(z.string().trim().min(1)).min(1),
106	  }).strict(),
107	}).strict();
108	export type ImplementationEvidence = z.infer<typeof implementationEvidenceSchema>;
109	
110	export const canonicalProcedureSchema = z.object({
111	  id: z.string().regex(/^[a-z][a-z0-9-]{2,79}$/),
112	  version: z.string().regex(/^\d{4}\.\d{2}\.\d{2}-v\d+$/),
113	  maturity: procedureMaturitySchema,
114	  title: bilingualSchema,
115	  role: procedureRoleSchema,
116	  blueprintStage: procedureStageSchema,
117	  owner: z.object({role: z.string().trim().min(1), approvedBy: z.string().trim().min(1).optional()}).strict(),
118	  objective: z.string().trim().min(1),
119	  product: z.string().trim().min(1),
120	  procedure: z.array(procedureStepSchema).min(1),
121	  output: z.object({schemaId: z.string().regex(/^[a-z][a-z0-9_.-]*$/), fields: z.array(procedureOutputFieldSchema).min(1)}).strict(),
122	  evidence: z.object({
123	    hierarchy: z.array(z.string().trim().min(1)).min(1),
124	    rules: z.array(z.string().trim().min(1)).min(1),
125	    materialClaimsRequireSupport: z.literal(true),
126	  }).strict(),
127	  tests: qualitySchema,
128	  source: z.object({path: z.string().trim().min(1), effectiveDate: z.iso.date(), supersedes: z.string().min(1).optional()}).strict(),
129	  knowledge: z.object({
130	    houseProcedureIds: z.array(z.string().regex(/^(IN|EMP|Q|D|OP|ES|PR|MA|MK|RF|LC)-\d{2}$/)).default([]),
131	    authorities: z.array(procedureAuthoritySchema).default([]),
132	    referenceDataKeys: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)).default([]),
133	    legalReviewRequired: z.boolean().default(false),
134	  }).strict().default({houseProcedureIds: [], authorities: [], referenceDataKeys: [], legalReviewRequired: false}),
135	
136	  /** Candidate and production detail. Drafts may omit these while the method is being written. */
137	  prerequisites: z.array(z.string().trim().min(1)).default([]),
138	  dependencies: z.array(z.string().regex(/^[a-z][a-z0-9-]{2,79}$/)).default([]),
139	  decisionRules: z.array(z.string().trim().min(1)).default([]),
140	  redFlags: z.array(z.string().trim().min(1)).default([]),
141	  stopConditions: z.array(z.string().trim().min(1)).default([]),
142	  exceptions: z.array(z.string().trim().min(1)).default([]),
143	  templates: z.array(z.string().regex(/^[a-z][a-z0-9-]{2,79}$/)).default([]),
144	  examples: z.object({positive: z.array(z.string().min(1)).default([]), negative: z.array(z.string().min(1)).default([])}).default({positive: [], negative: []}),
145	  runtime: runtimeSchema.default({
146	    orchestration: "deterministic_pipeline",
147	    peerHandoffs: false,
148	    maxModelCalls: 0,
149	    modelPurpose: [],
150	    allowedTools: [],
151	  }),
152	  /**
153	   * Evidence that the procedure is connected to executable code and the product rail.
154	   * Candidates may omit it while being built. Anything from `implemented` up may not.
155	   */
156	  implementation: implementationEvidenceSchema.optional(),
157	  /**
158	   * Independent reviews on record. `ai_independent_review` is a verification separate from the
159	   * implementation (back to the sources, numbers recalculated, definitions and exceptions
160	   * tested, adversarial and consistency runs); it is never a human approval and is recorded as
161	   * such. A rung above `implemented` needs at least one that passed or passed with conditions.
162	   */
163	  reviews: z.array(z.object({
164	    reviewId: z.string().regex(/^[a-z0-9][a-z0-9_.-]{2,120}$/),
165	    kind: z.literal("ai_independent_review"),
166	    result: z.enum(["pass", "conditional", "fail"]),
167	    recordPath: z.string().trim().min(1),
168	  }).strict()).default([]),
169	  /**
170	   * Evidence of the runs a rung needs: gold, adversarial and consistency. Ids of recorded runs,
171	   * never prose. `tested` and above require all three.
172	   */
173	  testRuns: z.object({
174	    gold: z.array(z.string().min(1)).default([]),
175	    adversarial: z.array(z.string().min(1)).default([]),
176	    consistency: z.array(z.string().min(1)).default([]),
177	  }).strict().default({gold: [], adversarial: [], consistency: []}),
178	}).strict().superRefine((procedure, context) => {
179	  duplicateIssues(procedure.procedure.map((step) => step.id), ["procedure"], context);
180	  duplicateIssues(procedure.output.fields.map((field) => field.id), ["output", "fields"], context);
181	  duplicateIssues(procedure.dependencies, ["dependencies"], context);
182	  duplicateIssues(procedure.templates, ["templates"], context);
183	  duplicateIssues(procedure.knowledge.houseProcedureIds, ["knowledge", "houseProcedureIds"], context);
184	  duplicateIssues(procedure.knowledge.authorities, ["knowledge", "authorities"], context);
185	  duplicateIssues(procedure.knowledge.referenceDataKeys, ["knowledge", "referenceDataKeys"], context);
186	
187	  if (procedure.runtime.maxModelCalls === 0 && procedure.runtime.modelPurpose.length > 0) {
188	    context.addIssue({code: "custom", path: ["runtime", "modelPurpose"], message: "a deterministic procedure cannot declare a model purpose"});
189	  }
190	  if (procedure.runtime.maxModelCalls > 0 && procedure.runtime.modelPurpose.length === 0) {
191	    context.addIssue({code: "custom", path: ["runtime", "modelPurpose"], message: "every model call needs a narrow declared purpose"});
192	  }
193	  if (procedure.knowledge.legalReviewRequired && !procedure.knowledge.authorities.includes("LEI")) {
194	    context.addIssue({code: "custom", path: ["knowledge", "legalReviewRequired"], message: "legal review requires LEI authority"});
195	  }
196	
197	  if (procedure.maturity === "draft") return;
198	  const candidateRequirements: Array<[keyof typeof procedure, unknown[]]> = [
199	    ["prerequisites", procedure.prerequisites],
200	    ["decisionRules", procedure.decisionRules],
201	    ["redFlags", procedure.redFlags],
202	    ["stopConditions", procedure.stopConditions],
203	  ];
204	  for (const [field, value] of candidateRequirements) {
205	    if (value.length === 0) context.addIssue({code: "custom", path: [field], message: `${procedure.maturity} procedures require ${field}`});
206	  }
207	
208	  const rank = maturityRank(procedure.maturity);
209	  if (rank >= maturityRank("implemented") && !procedure.implementation) {
210	    context.addIssue({code: "custom", path: ["implementation"], message: `${procedure.maturity} procedures require executable implementation evidence`});
211	  }
212	  if (rank >= maturityRank("ai_reviewed") && !procedure.reviews.some((review) => review.result !== "fail")) {
213	    context.addIssue({code: "custom", path: ["reviews"], message: `${procedure.maturity} procedures require a recorded independent review that passed or passed with conditions`});
214	  }
215	  if (rank >= maturityRank("tested")) {
216	    for (const kind of ["gold", "adversarial", "consistency"] as const) {
217	      if (procedure.testRuns[kind].length === 0) context.addIssue({code: "custom", path: ["testRuns", kind], message: `${procedure.maturity} procedures require recorded ${kind} runs`});
218	    }
219	  }
220	  if (rank >= maturityRank("ready_for_founder") && (procedure.examples.positive.length === 0 || procedure.examples.negative.length === 0)) {
221	    context.addIssue({code: "custom", path: ["examples"], message: `${procedure.maturity} procedures require positive and negative examples`});
222	  }
223	  if (procedure.maturity === "production" && !procedure.owner.approvedBy) {
224	    context.addIssue({code: "custom", path: ["owner", "approvedBy"], message: "production procedures require the founder's approval on record"});
225	  }
226	});
227	export type CanonicalProcedure = z.infer<typeof canonicalProcedureSchema>;
228	
229	export type CompiledProcedureSkill = {
230	  skillId: string;
231	  procedureId: string;
232	  procedureVersion: string;
233	  compilerVersion: string;
234	  sourceHash: string;
235	  maturity: ProcedureMaturity;
236	  role: ProcedureRole;
237	  blueprintStage: ProcedureStage;
238	  instructions: string;
239	  outputSchema: Record<string, unknown>;
240	  runtime: CanonicalProcedure["runtime"];
241	  knowledge: CanonicalProcedure["knowledge"];
242	  templates: string[];
243	  dependencies: string[];
244	  implementation: CanonicalProcedure["implementation"];
245	  reviews: CanonicalProcedure["reviews"];
246	  testRuns: CanonicalProcedure["testRuns"];
247	};
248	
249	/** Compile a reviewed procedure into the only form the runtime is allowed to execute. */
250	export function compileProcedure(raw: CanonicalProcedure): CompiledProcedureSkill {
251	  const procedure = canonicalProcedureSchema.parse(raw);
252	  const sourceHash = sha256(stableJson(procedure));
253	  return {
254	    skillId: `offroad.${procedure.id}@${procedure.version}`,
255	    procedureId: procedure.id,
256	    procedureVersion: procedure.version,
257	    compilerVersion: procedureCompilerVersion,
258	    sourceHash,
259	    maturity: procedure.maturity,
260	    role: procedure.role,

