import {reconcileCovenantDefinitions} from \"./packages/credit-playbook/src/executors/reconcile-covenant-definitions.ts\";
const netDebt=\"loans, financings and debentures plus derivative liabilities and any other onerous debt, minus cash and equivalents, financial investments and derivative assets, consolidated balance sheet\";
const ebitda=\"EBIT plus depreciation and amortization of the last twelve months as reported\";
const tiers=(references,direction=\"maximum\")=>[{limit:\"3.50\",direction,condition:{type:\"until_reference_settled\",referenceInstruments:references}},{limit:\"4.00\",direction,condition:{type:\"after_reference_settled\",referenceInstruments:references,requiresOrdinarySettlement:true}}];
const make=(settled)=>({asOfDate:\"2026-05-31\",nextMeasurementDate:\"2027-02-28\",instruments:[{id:\"deb-11\",indexName:\"Dívida Líquida/EBITDA\",netDebtDefinition:netDebt,ebitdaDefinition:ebitda,ebitdaAdjustments:[\"acquired company LTM EBITDA and sellers finance\"],measurement:{frequency:\"annual\",basis:\"audited consolidated statements\",fiscalYearEnd:\"02-28\"},tiers:tiers([\"cra-eco-8\"]),anchor:{document:\"escritura_11a_emissao.pdf\",clause:\"4.22.3(j)\"}},{id:\"deb-13\",indexName:\"Dívida Líquida/EBITDA\",netDebtDefinition:netDebt,ebitdaDefinition:ebitda,measurement:{frequency:\"annual\",basis:\"audited consolidated statements\",fiscalYearEnd:\"02-28\"},tiers:tiers([\"cra-eco-5\",\"cra-eco-257\"]),anchor:{document:\"escritura_13a_emissao.pdf\",clause:\"7.24.3(VIII)\"}},{id:\"deb-15\",indexName:\"Dívida Líquida/EBITDA\",netDebtDefinition:netDebt,ebitdaDefinition:ebitda,measurement:{frequency:\"annual\",basis:\"audited consolidated statements\",fiscalYearEnd:\"02-28\"},tiers:tiers([\"cra-eco-257\"]),anchor:{document:\"escritura_15a_emissao.pdf\",clause:\"7.26.3\"}}],referenceSettlements:[{instrument:\"cra-eco-8\",maturityDate:\"2025-04-15\",settledOrdinarily:settled,anchor:{document:\"af_11a_emissao.pdf\"}},{instrument:\"cra-eco-5\",maturityDate:\"2025-04-16\",settledOrdinarily:settled,anchor:{document:\"af_13a_emissao.pdf\"}},{instrument:\"cra-eco-257\",maturityDate:\"2025-12-29\",settledOrdinarily:settled,anchor:{document:\"cra_257_relatorio_mensal_4t25.pdf\"}}],reported:{value:\"4.72\",definition:\"net debt per the contractual definition over LTM EBITDA, pro forma, per note 15\",netDebtDefinitionMatches:\"same\",ebitdaOpened:false,anchor:{document:\"01_ITR_1T26_31mai2026.pdf\",page:40}}});
const summarize=(x)=>({covenants:x.covenants.map(c=>({instrument:c.instrument,limit:c.applicableLimit,tier:c.applicableTier,state:c.limitState,comparison:c.comparability,headroom:c.headroom,status:c.status,conditions:c.limitConditions})),definitions:x.definitionsAgree,unproven:x.unprovenConditions,inputFingerprint:x.trace.inputFingerprint,outputFingerprint:x.trace.outputFingerprint});
const outputs={};
