  6	/**
  7	 * Executor of the method `reconcile-covenant-definitions`. It never writes "breached": it
  8	 * resolves which tier applies from proven facts, says whether the reported index is comparable
  9	 * to the contractual definition, and only then measures headroom. An unproven condition leaves
 10	 * the limit unresolved and the item conditioned, with the reason.
 11	 */
 12	const anchorSchema = z.object({document: z.string().min(1), clause: z.string().optional(), page: z.number().int().positive().optional()}).strict();
 13	const ratio = z.string().regex(/^\d+(\.\d+)?$/);
 14	
 15	export const covenantTierSchema = z.object({
 16	  limit: ratio,
 17	  direction: z.enum(["maximum", "minimum"]).default("maximum"),
 18	  condition: z.discriminatedUnion("type", [
 19	    z.object({type: z.literal("unconditional")}).strict(),
 20	    z.object({type: z.literal("until_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
 21	    z.object({type: z.literal("after_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1), requiresOrdinarySettlement: z.boolean().default(true)}).strict(),
 22	  ]),
 23	}).strict();
 24	
 25	export const covenantInstrumentSchema = z.object({
 26	  id: z.string().min(1),
 27	  indexName: z.string().min(1),
 28	  netDebtDefinition: z.string().min(1),
 29	  ebitdaDefinition: z.string().min(1),
 30	  /** Adjustments beyond the base definition (acquisition pro forma, sellers finance, ...). */
 31	  ebitdaAdjustments: z.array(z.string().min(1)).default([]),
 32	  measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), basis: z.string().min(1), fiscalYearEnd: z.string().regex(/^\d{2}-\d{2}$/)}).strict(),
 33	  tiers: z.array(covenantTierSchema).min(1),
 34	  anchor: anchorSchema,
 35	}).strict();
 36	
 37	export const covenantReconciliationInputSchema = z.object({
 38	  asOfDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
 39	  nextMeasurementDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
 40	  instruments: z.array(covenantInstrumentSchema).min(1),
 41	  referenceSettlements: z.array(z.object({
 42	    instrument: z.string().min(1),
 43	    maturityDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
 44	    /** True only with evidence of ordinary settlement; null when the base does not prove it. */
 45	    settledOrdinarily: z.boolean().nullable(),
 46	    anchor: anchorSchema,
 47	  }).strict()).default([]),
 48	  reported: z.object({
 49	    value: ratio,
 50	    definition: z.string().min(1),
 51	    /** Whether the reported net debt definition matches the contractual one, from a component comparison. */
 52	    netDebtDefinitionMatches: z.enum(["same", "differs", "unknown"]),
 53	    /** Whether the company opens the EBITDA used, so adjustments can be compared. */
