 85	
 86	export function reconcileCovenantDefinitions(raw: CovenantReconciliationInput): CovenantReconciliationOutput {
 87	  const input = covenantReconciliationInputSchema.parse(raw);
 88	  const settlements = new Map(input.referenceSettlements.map((entry) => [entry.instrument, entry]));
 89	  const unproven = new Set<string>();
 90	
 91	  const netDebtDefinitions = new Set(input.instruments.map((instrument) => instrument.netDebtDefinition.trim()));
 92	  const ebitdaBases = new Set(input.instruments.map((instrument) => instrument.ebitdaDefinition.trim()));
 93	  const adjustmentsDiffer = input.instruments.filter((instrument) => instrument.ebitdaAdjustments.length > 0).map((instrument) => `${instrument.id}: ${instrument.ebitdaAdjustments.join("; ")}`);
 94	
 95	  const covenants = [...input.instruments].sort((a, b) => a.id.localeCompare(b.id)).map((instrument) => {
 96	    const conditions: string[] = [];
 97	    let applicable: {limit: string; tier: number} | null = null;
 98	    instrument.tiers.forEach((tier, index) => {
 99	      if (applicable) return;
100	      const condition = tier.condition;
101	      if (condition.type === "unconditional") { applicable = {limit: tier.limit, tier: index}; return; }
102	      const facts = condition.referenceInstruments.map((reference) => settlements.get(reference) ?? null);
103	      const allMatured = facts.every((fact) => fact !== null && fact.maturityDate <= input.asOfDate);
104	      const allSettled = facts.every((fact) => fact !== null && fact.settledOrdinarily === true);
105	      const anyUnknown = facts.some((fact) => fact === null || fact.settledOrdinarily === null);
106	      if (condition.type === "until_reference_settled") {
107	        // The lower tier stays while a reference instrument is alive; once all have matured the
108	        // next tier decides, and the proof it needs is recorded there, once.
109	        if (!allMatured) applicable = {limit: tier.limit, tier: index};
110	        return;
111	      }
112	      if (allSettled) { applicable = {limit: tier.limit, tier: index}; return; }
113	      if (anyUnknown) conditions.push(`the ${tier.limit}x tier requires proof of ordinary settlement of ${condition.referenceInstruments.join(", ")}; the base does not prove it`);
114	    });
115	    for (const condition of conditions) unproven.add(`${instrument.id}: ${condition}`);
116	
117	    const comparabilityReasons: string[] = [];
118	    if (input.reported.netDebtDefinitionMatches === "differs") comparabilityReasons.push("the reported net debt definition differs from the contractual one");
119	    if (input.reported.netDebtDefinitionMatches === "unknown") comparabilityReasons.push("the reported net debt definition could not be compared component by component");
120	    if (!input.reported.ebitdaOpened) comparabilityReasons.push("the company does not open the EBITDA used in the reported index");
121	    if (instrument.ebitdaAdjustments.length > 0) comparabilityReasons.push(`this indenture adjusts EBITDA (${instrument.ebitdaAdjustments.join("; ")}) and the reported index does not show the adjustment`);
122	    const comparability: "comparable" | "conditional" | "not_comparable" = input.reported.netDebtDefinitionMatches === "differs" ? "not_comparable" : comparabilityReasons.length > 0 ? "conditional" : "comparable";
123	
124	    let headroom: {absolute: string; relative: string | null} | null = null;
125	    let status: "within_limit" | "above_limit_interim" | "unresolved" = "unresolved";
126	    if (applicable && comparability !== "not_comparable") {
127	      const limit = d((applicable as {limit: string}).limit);
128	      const actual = d(input.reported.value);
129	      const absolute = limit.minus(actual);
130	      headroom = {absolute: out(absolute), relative: limit.isZero() ? null : out(absolute.div(limit))};
131	      status = absolute.gte(0) ? "within_limit" : "above_limit_interim";
132	    }
133	    return {
134	      instrument: instrument.id,
135	      indexName: instrument.indexName,
136	      applicableLimit: applicable ? (applicable as {limit: string}).limit : null,
137	      applicableTier: applicable ? (applicable as {tier: number}).tier : null,
138	      limitState: applicable ? "resolved" as const : "insufficient_evidence" as const,
139	      limitConditions: conditions,
140	      comparability,
141	      comparabilityReasons,
142	      headroom,
143	      status,
144	      anchor: instrument.anchor,
145	    };
146	  });
147	
148	  const body = {
149	    schemaVersion: "method.reconcile-covenant-definitions.v1" as const,
150	    asOfDate: input.asOfDate,
151	    nextMeasurementDate: input.nextMeasurementDate,
152	    covenants,
153	    definitionsAgree: {netDebt: netDebtDefinitions.size === 1, ebitdaBase: ebitdaBases.size === 1, ebitdaAdjustmentsDiffer: adjustmentsDiffer},
154	    unprovenConditions: [...unproven].sort(),
155	  };
156	  return {...body, trace: {calculations: ["structure.covenant_headroom", "financial.net_leverage"], inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(body)}};
157	}
